//! The raw C APIs, generated by `build.rs` from the system headers: one module per library. Only the safe
//! wrappers call into them; nothing here opens a device by itself.

/// libva (`va.h`, `va_drm.h`, `va_drmcommon.h`, `va_enc_hevc.h`), linked as `libva` and `libva-drm`.
#[allow(
    unsafe_code,
    dead_code,
    unused,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    unsafe_op_in_unsafe_fn,
    clippy::all,
    clippy::pedantic
)]
pub(crate) mod va {
    include!(concat!(env!("OUT_DIR"), "/va.rs"));
}

/// GBM (`gbm.h`), linked as `libgbm`.
#[allow(
    unsafe_code,
    dead_code,
    unused,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    unsafe_op_in_unsafe_fn,
    clippy::all,
    clippy::pedantic
)]
pub(crate) mod gbm {
    include!(concat!(env!("OUT_DIR"), "/gbm.rs"));
}

#[cfg(test)]
#[allow(unsafe_code)]
mod tests {
    use std::ffi::CStr;

    // Links and calls libva without opening anything: `vaErrorStr` maps a status to a static string.
    #[test]
    fn libva_links() {
        // SAFETY: vaErrorStr takes any status and returns a pointer to a static, NUL-terminated string.
        let text = unsafe { CStr::from_ptr(super::va::vaErrorStr(super::va::VA_STATUS_SUCCESS as _)) };
        assert_eq!(text.to_str().unwrap(), "success (no error)");
        assert_eq!(super::va::VAProfileHEVCMain, 17);
        assert_eq!(super::va::VA_RC_CBR, 0x2);
    }
}
